import sys

def main():
    data = sys.stdin.read().strip().split()
    n, k = map(int, data)

    if k == 0:
        # k=0，输出升序
        print("YES")
        print(*range(1, n+1))
    elif k == -1:
        # k=-1，交替出两端
        print("YES")
